import {industries,capacityLabels,fields,calculate} from './core.js';
const form=document.querySelector('#form'),results=document.querySelector('#results'),errors=document.querySelector('#errors');
const money=v=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:0}).format(v);
document.querySelector('#industry').innerHTML=Object.entries(industries).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');
document.querySelector('#fields').innerHTML=Object.entries(fields).map(([k,v],i)=>`${i===0?'<h3 class="field-heading">Сейчас / фактические показатели</h3>':i===5?'<h3 class="field-heading">Цели / ваши предположения</h3>':''}<label><span id="label-${k}">${v}</span><input name="${k}" type="number" min="0" step="any" required aria-describedby="err-${k}"><span class="error" id="err-${k}"></span></label>`).join('');
function invalidate(){document.querySelector('#consultation').hidden=true;results.innerHTML='<h2>02 / Результат диагностики</h2><p>Данные изменены. Нажмите «Рассчитать потенциал» для актуального результата.</p>';document.querySelector('#label-capacity').textContent=capacityLabels[form.elements.industry.value];}
form.addEventListener('input',invalidate);
form.elements.period.addEventListener('change',()=>{for(const k of Object.keys(fields))form.elements[k].value='';document.querySelector('#confirm').checked=false;invalidate();});
document.querySelector('#demo').onclick=()=>{const demo={leads:1000,conversion:20,repeat:100,ticket:1000,capacity:500,targetConversion:30,targetRepeat:150,targetTicket:1200};for(const[k,v]of Object.entries(demo))form.elements[k].value=v;document.querySelector('#confirm').checked=false;invalidate();errors.textContent='Вымышленные данные для проверки. Подтвердите отсутствие пересечений перед расчётом.';};
form.onsubmit=e=>{e.preventDefault();errors.textContent='';for(const k of Object.keys(fields)){document.querySelector('#err-'+k).textContent='';form.elements[k].removeAttribute('aria-invalid');}const d=Object.fromEntries(new FormData(form));for(const k of Object.keys(fields))d[k]=d[k].trim()===''?null:Number(d[k]);const r=calculate(d);for(const[k,v]of Object.entries(r.errors)){const el=document.querySelector('#err-'+k);if(el)el.textContent=v;form.elements[k]?.setAttribute('aria-invalid','true');}if(Object.keys(r.errors).length||!document.querySelector('#confirm').checked){errors.textContent=Object.keys(r.errors).length?'Исправьте отмеченные поля.':'Подтвердите отсутствие пересечений покупок.';invalidate();form.querySelector('[aria-invalid="true"]')?.focus();return;}
document.querySelector('#consultation').hidden=false;
const max=r.scenarios[2].revenue||1;
results.innerHTML=`<h2>02 / Потенциал выручки</h2><p>${industries[d.industry]} · ${form.elements.period.selectedOptions[0].textContent}</p><small>ТЕКУЩАЯ РАСЧЁТНАЯ ВЫРУЧКА</small><div class="big">${money(r.current)}</div><p>Дополнительный оборот: <strong>${money(r.scenarios[0].delta)} — ${money(r.scenarios[2].delta)}</strong></p><p class="note">Сценарий, не гарантия результата. Качество данных: заполнено 8 из 8 показателей, пересечения подтверждены пользователем; внешняя проверка не проводилась. Это не вероятность успеха.</p>${r.scenarios.map(s=>`<article><div class="row"><strong>${s.name}</strong><b>+${money(s.delta)}</b></div><meter min="0" max="${max}" value="${s.revenue}" aria-label="${s.name}: ${money(s.revenue)}"></meter><p>Выручка ${money(s.revenue)} · достижение цели ${s.factor*100}%${s.capped?' · ограничено мощностью':''}</p><details><summary>Три точки роста и расчёт</summary>${['Конверсия','Повторные покупки','Средний чек'].map((label,i)=>`<p>${label}: +${money(s.parts[i])}</p>`).join('')}<p>Конверсия ${s.conversion.toFixed(2)}%; повторных покупок до ограничения ${s.repeat}; чек ${money(s.ticket)}. Итого ${s.purchases.toFixed(2)} покупки × ${money(s.ticket)}.</p></details></article>`).join('')}<section class="next-steps"><h3>Что означает результат</h3><p>Сейчас расчёт даёт <strong>${money(r.current)}</strong> за выбранный период. Суммы со знаком «+» показывают возможную дополнительную выручку к этой базе, если изменятся заданные вами показатели.</p><p>В сценариях достигается 25%, 50% или 100% разницы до ваших целей. Это не вероятность результата и не отраслевой прогноз. Поток обращений и мощность остаются прежними.</p><h3>С чего начать</h3><p>Выберите один рычаг, для которого у вас есть данные и возможность изменить процесс. Сумма рядом с рычагом показывает вклад в сценарии, но сама по себе не определяет приоритет работы.</p><ol><li><strong>Конверсия.</strong> Разберите обращения за завершённый период: сколько дошло до первой оплаты, сколько завершилось отказом и сколько ещё в работе. Проверьте причины отказов. Для одного изменения процесса отслеживайте долю первых оплат при сопоставимом потоке обращений.</li><li><strong>Повторные покупки.</strong> Определите, когда клиенту обычно снова нужна услуга или товар и где теряется возвращение. Проверьте один способ повторного обращения с согласия клиента. Считайте повторные покупки отдельно от первых.</li><li><strong>Средний чек.</strong> Посмотрите состав покупок и возможность предложить полезное дополнение. Перед изменением цены или акцией оцените себестоимость, скидку и возможное изменение спроса. Рост выручки не означает рост прибыли.</li></ol><p><strong>Для обсуждения с командой:</strong> запишите одно действие, ответственного, дату проверки и показатель до изменения. После проверки сравните результат и условия периода.</p><p class="note">Если исходные значения оценены примерно, сначала проверьте их по учёту. Калькулятор не моделирует реакцию спроса на цену и не определяет выгодность акции без затрат.</p></section><details><summary>Исходные данные и предположения</summary>${Object.entries(fields).map(([k,v])=>`<p>${v}: ${d[k]}</p>`).join('')}<p>Доли реализации целей: 25 / 50 / 100%. Объём обращений и мощность неизменны. Чек одинаков для первых и повторных покупок. Затраты не введены: прирост прибыли неизвестен. Денежные итоги округлены только при отображении.</p></details><p>Какие из этих возможностей подходят вашему бизнесу? Разберём данные и определим первые шаги.</p><a class="result-cta" href="#consultation">Разобрать результат с Маргаритой →</a>`;};
invalidate();
